const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const prices = data.slice(1, 1 + n);

prices.sort((a, b) => a - b);

let total = 0;
for (let i = 0; i < n; i++) {
  total += prices[i];
}

for (let i = n - 3; i >= 0; i -= 3) {
  total -= prices[i];
}

console.log(total);
